{"code": "import re,itertools
hist=load_history(); pairs=[]; earlypairs=[]
for h in hist:
 if h['family']!='univariate_regression': continue
 cs=[]
 for let,txt in re.findall(r'### Choice ([A-Z])\s*(.*?)(?=### Choice|## Your answer|\Z)',h['question'],re.S):
  def get(p):
   m=re.search(p,txt); return m.group(1) if m else None
  opt=get(r'- Optimizer: (\w+)'); lr=get(r'- Learning rate: ([\deE.+-]+)'); depth=get(r'- Depth: (\d+)'); width=get(r'- Width: (\d+)'); res=get(r'- Residual connections: (True|False)'); act=get(r'- Activation: (\w+)'); ln=get(r'- Layer norm per layer: (\[[^\]]*\])')
  if not all([opt,lr,depth,width,res,act,ln]): continue
  cs.append(dict(letter=let,opt=opt,lr=float(lr),depth=int(depth),width=int(width),res=res,act=act,ln=[v.strip()=='True' for v in ln[1:-1].split(',')]))
 order=re.findall('[A-E]',h['answer'])
 if len(order)<2: continue
 for a,b in itertools.combinations(cs,2):
  if a['opt']==b['opt']=='Adagrad' and a['lr']!=b['lr']:
   l,r=sorted([a,b],key=lambda c:c['lr']); win=order.index(r['letter'])<order.index(l['letter']); pairs.append((h['question_id'],win,l,r))
   if l['res']==r['res']=='True' and l['depth']==r['depth'] and l['width']==r['width'] and l['act']==r['act'] and l['ln'][0] and not r['ln'][0]: earlypairs.append((h['question_id'],not win,l,r))
print('history unequal Adagrad',len(pairs),'higher hits',sum(p[1] for p in pairs),'misses',sum(not p[1] for p in pairs))
print('early residual same shape vs higher late',len(earlypairs),'early wins',sum(p[1] for p in earlypairs)); print(earlypairs)
"}

